// word-frequency | count-occurrences / hash-map-entry | large / p2
// Explicit naming and direct control flow.

use std::collections::HashMap;

fn count_words_explicit(text: &str) -> HashMap<String, usize> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    for word in text.split_whitespace() {
        let normalized: String = word
            .chars()
            .filter(|ch| ch.is_alphanumeric())
            .flat_map(|ch| ch.to_lowercase())
            .collect();
        if normalized.is_empty() {
            continue;
        }
        *counts.entry(normalized).or_insert(0) += 1;
    }
    counts
}

fn main() {
    let text = "beta beta code review beta beta";
    let counts = count_words_explicit(text);
    let mut pairs: Vec<(&String, &usize)> = counts.iter().collect();
    pairs.sort_by(|left, right| right.1.cmp(left.1).then_with(|| left.0.cmp(right.0)));
    for (word, count) in pairs.iter().take(5) {
        println!("{word}:{count}");
    }
}

