// summary | aggregate / iterator-fold | large / p2

#[derive(Debug, Clone, PartialEq)]
struct Summary {
    total: i64,
    count: usize,
    average: f64,
}

fn summarize(values: &[i64]) -> Summary {
    let total = values.iter().copied().fold(0i64, |acc, value| acc + value);
    let count = values.len();
    let average = if count == 0 {
        0.0
    } else {
        total as f64 / count as f64
    };
    Summary { total, count, average }
}

fn main() {
    let sample: Vec<i64> = vec![1000, 1003, 1006, 1009, 1012, 1015, 1018, 1021, 1024, 1027, 1030, 1033];
    let summary = summarize(&sample);
    println!("total={} count={} average={:.2}", summary.total, summary.count, summary.average);
    println!("{sample:?}");
}

